using System;using System.Linq;
namespace IdleIntelligence.Core {
 [Serializable]public sealed class BalanceItemSnapshot {public string id,type,rarity;public int level,forge;public BalanceItemSnapshot Copy()=>(BalanceItemSnapshot)MemberwiseClone();}
 [Serializable]public sealed class BalanceObservation {
  public bool lifetimeCreditsRecorded,lifetimeEligibleRecorded,lifetimeDataRecorded;public NumberData lifetimeCredits=ScientificNumber.Zero.ToData(),lifetimeEligible=ScientificNumber.Zero.ToData(),lifetimeData=ScientificNumber.Zero.ToData();public bool metaBalancesRecorded,projectLevelsRecorded,modelLevelsRecorded,fullRecorded,runCreditsRecorded,hardwareRecorded,labsRecorded;public long gems;public bool paidIncome,adFree;public string[] nodeIds=Array.Empty<string>(),equipped=Array.Empty<string>();public int[] research=Array.Empty<int>(),modelLevels=Array.Empty<int>();public BalanceItemSnapshot[] inventory=Array.Empty<BalanceItemSnapshot>();public NumberData totalINT=ScientificNumber.Zero.ToData(),unspentINT=ScientificNumber.Zero.ToData(),spentINT=ScientificNumber.Zero.ToData(),availableAxioms=ScientificNumber.Zero.ToData(),totalAxioms=ScientificNumber.Zero.ToData(),knowledge=ScientificNumber.Zero.ToData();public double at;public NumberData credits,data,compute,users,income,dataRate,runCredits,cycleINT;public int quality,efficiency,integration,labs,items,nodes;public string model,training;public long[] hardware;
  public static BalanceObservation At(GameState s,bool full=false)=>new BalanceObservation{lifetimeCredits=s.LifetimeCreditsExact.ToData(),lifetimeEligible=s.LifetimeEligibleExact.ToData(),lifetimeData=s.LifetimeDataExact.ToData(),lifetimeCreditsRecorded=s.LifetimeCreditsExactRecorded,lifetimeEligibleRecorded=s.LifetimeEligibleExactRecorded,lifetimeDataRecorded=s.LifetimeDataExactRecorded,metaBalancesRecorded=true,projectLevelsRecorded=true,modelLevelsRecorded=true,fullRecorded=full,runCreditsRecorded=s.RunCreditsRecorded,gems=s.Retention.gems,paidIncome=PurchaseRules.Income(s)>1,adFree=PurchaseRules.AdFree(s),nodeIds=full?(string[])s.Workshop.nodes.Clone():Array.Empty<string>(),equipped=full?(string[])s.Workshop.equipped.Clone():Array.Empty<string>(),research=full?(int[])s.Research.Clone():Array.Empty<int>(),modelLevels=full?(int[])s.Meta.models.Clone():Array.Empty<int>(),inventory=full?s.Workshop.inventory.Select(i=>new BalanceItemSnapshot{id=i.id,type=i.type,rarity=ItemBalance.Rarities[i.rarity],level=i.level,forge=i.forge}).ToArray():Array.Empty<BalanceItemSnapshot>(),totalINT=s.Prestige.Total.ToData(),unspentINT=s.Prestige.Free.ToData(),spentINT=s.Prestige.Spent.ToData(),availableAxioms=ScientificNumber.FromData(s.Meta.available).ToData(),totalAxioms=ScientificNumber.FromData(s.Meta.total).ToData(),knowledge=ScientificNumber.FromData(s.Prestige.knowledge).ToData(),hardwareRecorded=true,labsRecorded=true,at=s.SavedAt,credits=s.Credits.ToData(),data=s.Data.ToData(),compute=Game.Compute(s).ToData(),users=Game.Users(s).ToData(),income=Game.Income(s).ToData(),dataRate=Game.DataRate(s).ToData(),runCredits=s.RunCredits.ToData(),cycleINT=s.Prestige.Cycle.ToData(),quality=s.Quality,efficiency=s.Efficiency,integration=s.Workshop.integration,labs=PrestigeAutomation.ResearchJobs(s).Count(),items=s.Workshop.inventory.Length,nodes=s.Workshop.nodes.Length,model=s.Workshop.activeModel,training=s.Training?.id??"",hardware=(long[])s.Hardware.Clone()};
  public BalanceObservation Copy(){var n=(BalanceObservation)MemberwiseClone();n.nodeIds=(string[])nodeIds.Clone();n.equipped=(string[])equipped.Clone();n.research=(int[])research.Clone();n.modelLevels=(int[])modelLevels.Clone();n.inventory=inventory.Select(i=>i.Copy()).ToArray();n.hardware=(long[])hardware.Clone();foreach(var f in typeof(BalanceObservation).GetFields().Where(f=>f.FieldType==typeof(NumberData)))f.SetValue(n,ScientificNumber.FromData((NumberData)f.GetValue(this)).ToData());return n;}
 }
 [Serializable]public sealed class BalanceEventMetric {public string key;public long count,completed;public double firstAt,seconds;public NumberData credits=ScientificNumber.Zero.ToData(),data=ScientificNumber.Zero.ToData();public BalanceEventMetric Copy()=>new BalanceEventMetric{key=key,count=count,completed=completed,firstAt=firstAt,seconds=seconds,credits=ScientificNumber.FromData(credits).ToData(),data=ScientificNumber.FromData(data).ToData()};}
 [Serializable]public sealed class BalanceRunRecord {
  public BalanceEventMetric[] events=Array.Empty<BalanceEventMetric>();public long droppedEventKinds;public long run,cycle,taps,droppedCheckpoints;public double observedFrom,endedAt,activeSeconds,offlineSeconds;public bool partial,automatic,hasEnd;public string kind="current";public NumberData credits=ScientificNumber.Zero.ToData(),data=ScientificNumber.Zero.ToData(),intReward=ScientificNumber.Zero.ToData(),axiomReward=ScientificNumber.Zero.ToData();public BalanceObservation start,end;public BalanceObservation[] checkpoints=Array.Empty<BalanceObservation>();
  public BalanceRunRecord Copy(bool deep=false){var n=(BalanceRunRecord)MemberwiseClone();n.events=events.Select(x=>x.Copy()).ToArray();n.credits=ScientificNumber.FromData(credits).ToData();n.data=ScientificNumber.FromData(data).ToData();n.intReward=ScientificNumber.FromData(intReward).ToData();n.axiomReward=ScientificNumber.FromData(axiomReward).ToData();n.start=deep?start?.Copy():start;n.end=deep?end?.Copy():end;n.checkpoints=deep?checkpoints.Select(x=>x.Copy()).ToArray():(BalanceObservation[])checkpoints.Clone();return n;}
 }
 [Serializable]public sealed class LocalBalanceHistory {
  public int schema=1;public bool measurementKnown,initialized=true,hasCurrent;public double measuredSince;public long archivedRuns,archivedPrestiges,archivedAxioms;public double archivedActiveSeconds,archivedOfflineSeconds;public NumberData archivedINT=ScientificNumber.Zero.ToData(),archivedAxiom=ScientificNumber.Zero.ToData();public BalanceRunRecord current;public BalanceRunRecord[] runs=Array.Empty<BalanceRunRecord>();
  public LocalBalanceHistory Copy(bool deep=false){var n=(LocalBalanceHistory)MemberwiseClone();n.current=current?.Copy(deep);n.runs=deep?runs.Select(x=>x.Copy(true)).ToArray():(BalanceRunRecord[])runs.Clone();n.archivedINT=ScientificNumber.FromData(archivedINT).ToData();n.archivedAxiom=ScientificNumber.FromData(archivedAxiom).ToData();return n;}
  static BalanceRunRecord Ensure(GameState s){var h=s.Journal.history;if(h.current==null){var p=BalanceObservation.At(s,true);h.hasCurrent=true;h.current=new BalanceRunRecord{run=s.Prestige.resets,cycle=s.Meta.resets,observedFrom=s.SavedAt,partial=!h.measurementKnown||s.SavedAt!=s.Workshop.runStartedAt,start=p,checkpoints=new[]{BalanceObservation.At(s)}};if(!h.measurementKnown)h.measuredSince=s.SavedAt;h.measurementKnown=true;}return h.current;}
  public static void Event(GameState s,LocalEvent e){if(ChallengeRules.Active(s))return;var r=Ensure(s);string key=e.type+(e.type.StartsWith("training-",StringComparison.Ordinal)?":"+e.job:"");var old=r.events.FirstOrDefault(x=>x.key==key);if(old==null){if(r.events.Length>=JournalCatalog.EventKeys){r.droppedEventKinds++;return;}old=new BalanceEventMetric{key=key,firstAt=e.at};r.events=r.events.Concat(new[]{old}).ToArray();}old.count++;if(new[]{"training-start","research-start","experiment-start","crafting_queued"}.Contains(e.type)&&e.costsRecorded){old.credits=ScientificNumber.FromData(old.credits).Add(ScientificNumber.FromData(e.creditCost)).ToData();old.data=ScientificNumber.FromData(old.data).Add(ScientificNumber.FromData(e.dataCost)).ToData();}if(e.type.EndsWith("-complete",StringComparison.Ordinal)&&e.durationRecorded){old.completed++;old.seconds+=e.actualSeconds;}}
  public static void Production(GameState s,double seconds,bool active,ScientificNumber credits,ScientificNumber data){if(ChallengeRules.Active(s))return;var r=Ensure(s);r.activeSeconds+=active?seconds:0;r.offlineSeconds+=active?0:seconds;r.credits=ScientificNumber.FromData(r.credits).Add(credits).ToData();r.data=ScientificNumber.FromData(r.data).Add(data).ToData();}
  public static void Tap(GameState s){if(!ChallengeRules.Active(s))Ensure(s).taps++;}
  public static void Checkpoint(GameState s,bool force=false){if(ChallengeRules.Active(s))return;var r=Ensure(s);if(!force&&s.SavedAt-r.checkpoints.Last().at<300000)return;var list=r.checkpoints.Concat(new[]{BalanceObservation.At(s)}).ToArray();if(list.Length>JournalCatalog.CurrentCheckpoints){var keep=list.Where((x,i)=>i==0||i==list.Length-1||i%2==0).ToArray();r.droppedCheckpoints+=list.Length-keep.Length;list=keep;}r.checkpoints=list;}
  public static void Close(GameState before,GameState after,string kind,ScientificNumber reward,ScientificNumber axiom=null){if(ChallengeRules.Active(before))return;var measured=before.Copy();Checkpoint(measured,true);var h=measured.Journal.history;var r=h.current;r.kind=kind;r.endedAt=before.SavedAt;r.hasEnd=true;r.end=BalanceObservation.At(before,true);r.intReward=reward.ToData();r.axiomReward=(axiom??ScientificNumber.Zero).ToData();r.automatic=before.Prestige.resetIntent||before.Meta.intentAxiom;var all=r.checkpoints;int stride=Math.Max(1,(int)Math.Ceiling((all.Length-2d)/(JournalCatalog.RunCheckpoints-2)));r.checkpoints=all.Where((x,i)=>i==0||i==all.Length-1||i%stride==0).TakeLast(JournalCatalog.RunCheckpoints).ToArray();r.droppedCheckpoints+=all.Length-r.checkpoints.Length;var runs=h.runs.Concat(new[]{r}).ToArray();foreach(var old in runs.Take(Math.Max(0,runs.Length-JournalCatalog.Runs))){h.archivedRuns++;if(old.kind=="prestige")h.archivedPrestiges++;if(old.kind=="axiom")h.archivedAxioms++;h.archivedActiveSeconds+=old.activeSeconds;h.archivedOfflineSeconds+=old.offlineSeconds;h.archivedINT=ScientificNumber.FromData(h.archivedINT).Add(ScientificNumber.FromData(old.intReward)).ToData();h.archivedAxiom=ScientificNumber.FromData(h.archivedAxiom).Add(ScientificNumber.FromData(old.axiomReward)).ToData();}h.runs=runs.Skip(Math.Max(0,runs.Length-JournalCatalog.Runs)).ToArray();h.measurementKnown=true;h.hasCurrent=false;h.current=null;after.Journal.history=h;Checkpoint(after,true);}
  public static void Validate(LocalBalanceHistory h){if(h==null||!h.initialized||h.schema!=1||h.runs==null||h.runs.Length>JournalCatalog.Runs||h.archivedRuns<0||!ScientificNumber.Finite(h.measuredSince)||h.measuredSince<0)throw new FormatException("Invalid balance history");foreach(var r in h.runs.Concat(h.current==null?Array.Empty<BalanceRunRecord>():new[]{h.current})){if(r==null||r.start==null||r.events==null||r.events.Length>JournalCatalog.EventKeys||r.events.Any(x=>x==null||string.IsNullOrEmpty(x.key)||x.count<0||!ScientificNumber.Finite(x.seconds)||x.seconds<0)||r.checkpoints==null||r.checkpoints.Length>JournalCatalog.CurrentCheckpoints||r.checkpoints.Any(x=>x==null)||!new[]{"current","prestige","axiom"}.Contains(r.kind))throw new FormatException("Invalid balance run");foreach(double v in new[]{r.observedFrom,r.endedAt,r.activeSeconds,r.offlineSeconds})if(!ScientificNumber.Finite(v)||v<0)throw new FormatException("Invalid balance time");foreach(var p in r.checkpoints.Concat(new[]{r.start}).Concat(r.end==null?Array.Empty<BalanceObservation>():new[]{r.end})){if(p.inventory==null||p.nodeIds==null||p.equipped==null||p.research==null||p.modelLevels==null||p.fullRecorded&&(p.equipped.Length!=ItemBalance.Slots.Length||p.research.Length!=Balance.Research.Length||p.modelLevelsRecorded&&p.modelLevels.Length!=MetaBalance.Models.Length||p.inventory.Length!=p.items)||p.hardware==null||p.hardware.Length!=Balance.Hardware.Length||p.hardware.Any(v=>v<0)||!ScientificNumber.Finite(p.at)||p.at<0)throw new FormatException("Invalid balance checkpoint");foreach(var f in typeof(BalanceObservation).GetFields().Where(f=>f.FieldType==typeof(NumberData)))ScientificNumber.FromData((NumberData)f.GetValue(p));}foreach(var n in new[]{r.credits,r.data,r.intReward,r.axiomReward})ScientificNumber.FromData(n);}}
 }
}
